 23	/**
 24	 * Answers whether this account can harvest a debris field now, and which one.
 25	 *
 26	 * Recycling is the closing half of the raid and expedition loop: the debris a
 27	 * battle leaves is income a player sends recyclers for. The field, its mass and
 28	 * the harvest hull are all host-read; the module only adds the feasibility — a
 29	 * field above a minimum mass that is not already being harvested, and an own
 30	 * body that carries the hull the host's recycle mission requires for that slot.
 31	 */
 32	class QueueableRecyclePlanner
 33	{
 34	    /** Bounded: at most this many candidate fields are inspected per decision. */
 35	    private const MAX_CANDIDATES = 20;
 36	
 37	    /** A field worth less than this metal-equivalent is not worth the trip. */
 38	    private const MIN_FIELD_MASS = 10_000;
 39	
 40	    public function __construct(
 41	        private PlayerServiceFactory $playerServiceFactory,
 42	    ) {
 43	    }
 44	
 45	    public function plan(int $playerId): ?QueueableRecycle
 46	    {
 47	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 48	        if ($profile === null) {
 49	            return null;
 50	        }
 51	
 52	        if (!User::query()->whereKey($playerId)->exists()) {
 53	            return null;
 54	        }
 55	
 56	        $player = $this->playerServiceFactory->make($playerId, true);
 57	
 58	        $refusals = app(RecentRefusals::class);
 59	        // A field or a body the gate just refused is not a mission, so nothing else remembers it: the
 60	        // harvest that was refused (the field was gone, the hull was short) is not offered again.
 61	        $covered = $this->coveredCoordinates($playerId)
 62	            + $this->openRecycleIntentCoordinates($playerId)
 63	            + $refusals->refusedTargets($playerId);
 64	        $refusedOrigins = $refusals->refusedOrigins($playerId);
 65	
 66	        // ponytail: scan the 20 largest fields and take the closest worth having; a
 67	        // distance cap on the scan is the upgrade path once accounts spread fleets
 68	        // across galaxies.
 69	        $fields = DebrisField::query()
 70	            ->orderByDesc('metal')
 71	            ->orderByDesc('crystal')
 72	            ->limit(self::MAX_CANDIDATES)
 73	            ->get();
 74	
 75	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
 76	        $best = null;
 77	
 78	        foreach ($fields as $field) {
 79	            $coordinateKey = "{$field->galaxy}:{$field->system}:{$field->planet}";
 80	            if (isset($covered[$coordinateKey])) {
 81	                continue;
 82	            }
 83	
 84	            $mass = (float) $field->metal + (float) $field->crystal + (float) $field->deuterium;
 85	            if ($mass < self::MIN_FIELD_MASS) {
 86	                continue;
 87	            }
 88	
 89	            $shipName = RecycleMission::getHarvesterMachineNameForPosition((int) $field->planet);
 90	            $origin = $this->origin($player, $shipName, $refusedOrigins) ?? $this->builderOrigin($player, $shipName, $refusedOrigins);
 91	            if ($origin === null) {
 92	                continue;
 93	            }
 94	
 95	            $coordinate = new Coordinate((int) $field->galaxy, (int) $field->system, (int) $field->planet);
 96	            if (!$this->canPayFlight($player, $origin, $shipName, $mass, $coordinate)) {
 97	                continue;
 98	            }
 99	
100	            $distance = $fleetMissions->calculateFleetMissionDistance($origin, $coordinate);
101	
102	            if ($best === null || $distance < $best['distance']) {
103	                $best = ['field' => $field, 'origin' => $origin, 'distance' => $distance, 'mass' => $mass];
104	            }
105	        }
106	
107	        if ($best === null) {
108	            return null;
109	        }
110	
111	        return app()->makeWith(QueueableRecycle::class, [
112	            'planetId' => $best['origin']->getPlanetId(),
113	            'targetGalaxy' => (int) $best['field']->galaxy,
114	            'targetSystem' => (int) $best['field']->system,
115	            'targetPosition' => (int) $best['field']->planet,
116	            'targetType' => PlanetType::DebrisField->value,
117	            'missionType' => RecycleMission::getTypeId(),
118	            'mass' => $best['mass'],
119	        ]);
120	    }
121	
122	    /**
123	     * Whether the origin can pay the harvest run with the hulls it would send, quoted the way the dispatch
124	     * quotes it. A body with no hull yet is the builder case: the hull is queued first, nothing flies now.
125	     */
126	    private function canPayFlight(PlayerService $player, PlanetService $origin, string $shipName, float $mass, Coordinate $coordinate): bool
127	    {
128	        $available = $origin->getShipUnits()->getAmountByMachineName($shipName);
129	        if ($available <= 0) {
130	            return true;
131	        }
132	
133	        $ship = ObjectService::getShipObjectByMachineName($shipName);
134	        $capacity = max(1, $ship->properties->capacity->calculate($player)->totalValue);
135	        $fleet = new UnitCollection();
136	        $fleet->addUnit($ship, max(1, min($available, (int) ceil($mass / $capacity))));
137	
138	        return app(FlightFuel::class)->affordable($player, $origin, $fleet, $coordinate, 10.0);
139	    }
140	
141	    /**
142	     * The first own body carrying the harvest hull. ponytail: first-body, not
143	     * closest-to-field; the closest-body scan is the upgrade path.
144	     *
145	     * @param array<int, true> $refusedOrigins own bodies the gate just refused a dispatch from
146	     */
147	    private function origin(PlayerService $player, string $shipName, array $refusedOrigins): ?PlanetService
148	    {
149	        foreach ($player->planets->all() as $planet) {
150	            if (! isset($refusedOrigins[$planet->getPlanetId()]) && $planet->getShipUnits()->getAmountByMachineName($shipName) > 0) {
151	                return $planet;
152	            }
153	        }
154	
155	        return null;
156	    }
157	
158	    /**
159	     * The own body that can build the harvest hull when none carries it yet: the
160	     * executor queues the hull before the field can be collected, so a field with no
161	     * hull on hand is still a harvest the account can take.
162	     *
163	     * @param array<int, true> $refusedOrigins own bodies the gate just refused a dispatch from
164	     */
165	    private function builderOrigin(PlayerService $player, string $shipName, array $refusedOrigins): ?PlanetService
166	    {
167	        foreach ($player->planets->all() as $planet) {
168	            if (! isset($refusedOrigins[$planet->getPlanetId()]) && ObjectService::objectRequirementsMet($shipName, $planet)) {
169	                return $planet;
170	            }
171	        }
172	
173	        return null;
174	    }
175	
176	    /** @return array<string, true> coordinates already being harvested */
177	    private function coveredCoordinates(int $playerId): array
178	    {
179	        $coordinates = [];
180	        foreach (FleetMission::query()
181	            ->where('user_id', $playerId)
182	            ->where('mission_type', RecycleMission::getTypeId())
183	            ->where('processed', 0)
184	            ->where('canceled', 0)
185	            ->get(['galaxy_to', 'system_to', 'position_to']) as $mission) {
186	            $coordinates["{$mission->galaxy_to}:{$mission->system_to}:{$mission->position_to}"] = true;
187	        }
188	
189	        return $coordinates;
190	    }
191	
192	    /** @return array<string, true> coordinates already decided but not yet dispatched */
193	    private function openRecycleIntentCoordinates(int $playerId): array
194	    {
195	        $coordinates = [];
196	        foreach (AiWorkItem::query()
197	            ->where('player_id', $playerId)
198	            ->where('kind', AiWorkKind::Recycle)
199	            ->whereIn('state', [AiWorkState::Pending, AiWorkState::Leased, AiWorkState::Retry])
200	            ->get(['payload']) as $item) {
201	            $payload = $item->payload ?? [];
202	            if (isset($payload['target_galaxy'], $payload['target_system'], $payload['target_position'])) {
203	                $coordinates["{$payload['target_galaxy']}:{$payload['target_system']}:{$payload['target_position']}"] = true;
204	            }
205	        }
206	
207	        return $coordinates;
208	    }
209	}

