 12	/**
 13	 * Interplanetary missiles are how a player thins a wall before the fleet arrives, so a planet that holds
 14	 * missiles and has a fresh report on a defended target inside the missile range fires them. The range,
 15	 * the missile count and the target's standing defence are the host's; the planner only asks. A volley the
 16	 * dispatch gate refused a moment ago is waited out, the way every other dispatch lane waits: the refusal
 17	 * is not a mission, so this read is the only thing that remembers it.
 18	 */
 19	class QueueableMissilePlanner
 20	{
 21	    /** The host's machine name for the missile object, the one catalogue name the host's own mission also reads. */
 22	    private const MISSILE = 'interplanetary_missile';
 23	
 24	    private const REPORT_FRESH_HOURS = 12;
 25	
 26	    /** A wall thinner than this is not worth a missile each. */
 27	    private const MIN_DEFENCE_UNITS = 20;
 28	
 29	    public function __construct(private PlayerServiceFactory $playerServiceFactory)
 30	    {
 31	    }
 32	
 33	    public function plan(int $playerId): ?QueueableMissile
 34	    {
 35	        if (!AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->exists()) {
 36	            return null;
 37	        }
 38	
 39	        if (!User::query()->whereKey($playerId)->exists()) {
 40	            return null;
 41	        }
 42	
 43	        $player = $this->playerServiceFactory->make($playerId, true);
 44	        $range = $player->getMissileRange();
 45	        if ($range < 1) {
 46	            return null;
 47	        }
 48	
 49	        // A refused volley is not a mission, so nothing else remembers it: the body the gate just
 50	        // refused to fire from, and the target it blamed, are not offered again inside the cooling.
 51	        // Without this the same planet fired at the same wall on every login and the host refused the
 52	        // same dispatch again (the DISPATCH_REFUSALS repeat).
 53	        $refusals = app(RecentRefusals::class);
 54	        $refusedOrigins = $refusals->refusedOrigins($playerId);
 55	        $refusedTargets = $refusals->refusedTargets($playerId);
 56	
 57	        $reportIds = Message::query()
 58	            ->where('user_id', $playerId)
 59	            ->whereNotNull('espionage_report_id')
 60	            ->where('created_at', '>=', now()->subHours(self::REPORT_FRESH_HOURS))
 61	            ->pluck('espionage_report_id');
 62	        if ($reportIds->isEmpty()) {
 63	            return null;
 64	        }
 65	
 66	        $reports = EspionageReport::query()->whereIn('id', $reportIds)->orderByDesc('id')->get();
 67	
 68	        foreach ($player->planets->all() as $planet) {
 69	            if (isset($refusedOrigins[$planet->getPlanetId()])) {
 70	                continue;
 71	            }
 72	
 73	            $missiles = $planet->getObjectAmount(self::MISSILE);
 74	            if ($missiles < 1) {
 75	                continue;
 76	            }
 77	
 78	            $origin = $planet->getPlanetCoordinates();
 79	            $best = null;
 80	            $bestWall = 0;
 81	
 82	            foreach ($reports as $report) {
 83	                if (isset($refusedTargets["{$report->planet_galaxy}:{$report->planet_system}:{$report->planet_position}"])) {
 84	                    continue;
 85	                }
 86	
 87	                if ((int) $report->planet_galaxy !== $origin->galaxy
 88	                    || abs((int) $report->planet_system - $origin->system) > $range
 89	                    || (int) $report->planet_user_id === $playerId) {
 90	                    continue;
 91	                }
 92	
 93	                $wall = (int) array_sum($report->defense ?? []);
 94	                // The host's own interceptor is not a wall: the missiles of the target's silo answer 1:1 elsewhere.
 95	                if ($wall < self::MIN_DEFENCE_UNITS || $wall <= $bestWall || $this->shielded($player, (int) $report->planet_user_id)) {
 96	                    continue;
 97	                }
 98	
 99	                $best = $report;
100	                $bestWall = $wall;
101	            }
102	
103	            if ($best === null) {
104	                continue;
105	            }
106	
107	            return app()->makeWith(QueueableMissile::class, [
108	                'originPlanetId' => $planet->getPlanetId(),
109	                'targetGalaxy' => (int) $best->planet_galaxy,
110	                'targetSystem' => (int) $best->planet_system,
111	                'targetPosition' => (int) $best->planet_position,
112	                'targetType' => (int) $best->planet_type,
113	                'missiles' => $missiles,
114	            ]);
115	        }
116	
117	        return null;
118	    }
119	
120	    private function shielded(PlayerService $player, int $targetUserId): bool
121	    {
122	        if ($targetUserId <= 0 || !User::query()->whereKey($targetUserId)->exists()) {
123	            return true;
124	        }
125	
126	        return $this->playerServiceFactory->make($targetUserId, true)->isNewbie($player);
127	    }
128	}

