 28	/**
 29	 * Answers whether this account can probe a neighbour now, and which one.
 30	 *
 31	 * Scouting is the ordinary first contact an experienced player makes with the
 32	 * galaxies around them, and it is what turns "no target intel" into the reports
 33	 * raids later depend on. The target is a foreign planet the account does not own
 34	 * and whose owner is neither in vacation mode nor the protected administrator —
 35	 * the same gates the host's own espionage mission applies — and the probe the
 36	 * mission consumes is the ship the host requires. The candidate list is the
 37	 * host's own planets table, so no target is named here.
 38	 *
 39	 * A target the account already holds fresh intel on, or already has a probe in
 40	 * flight toward, is skipped. Scouting is bounded: each neighbour is probed once
 41	 * per intel window, and the account waits for its own probe to come back before
 42	 * sending another instead of re-probing the same planets it cannot act on.
 43	 */
 44	class QueueableSpyPlanner
 45	{
 46	    /** Bounded: only this many unscouted, nearest candidate targets are inspected per decision. */
 47	    private const MAX_CANDIDATES = 20;
 48	
 49	    /** A report stays fresh this long; scouting and raiding agree on the window. */
 50	    private const INTEL_TTL_HOURS = 24;
 51	
 52	    /** A partial report on a valuable target gets this many probes; the host redacts ships below two and defence below three probes, so one probe re-reads the same redacted report. */
 53	    private const ESCALATED_PROBES = 5;
 54	
 55	    /** Metal-equivalent loot that makes a redacted report worth a probe volley. */
 56	    private const RICH_YIELD = 10_000.0;
 57	
 58	    public function __construct(
 59	        private PlayerServiceFactory $playerServiceFactory,
 60	        private PlanetServiceFactory $planetServiceFactory,
 61	        private ActivityIntelReader $activityIntelReader,
 62	        private IntelBook $intelBook,
 63	    ) {
 64	    }
 65	
 66	    public function plan(int $playerId, ?PlayerService $player = null): ?QueueableSpy
 67	    {
 68	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 69	        if ($profile === null) {
 70	            return null;
 71	        }
 72	
 73	        if (!User::query()->whereKey($playerId)->exists()) {
 74	            return null;
 75	        }
 76	
 77	        $player ??= $this->playerServiceFactory->make($playerId, true);
 78	
 79	        $refusals = app(RecentRefusals::class);
 80	        $skip = $this->freshIntelCoordinates($playerId)
 81	            + $this->inFlightCoordinates($playerId)
 82	            + $this->openSpyIntentCoordinates($playerId)
 83	            // A probe the gate just refused is not a mission, so nothing else remembers the target.
 84	            + $refusals->refusedTargets($playerId);
 85	        $selection = $this->target($player, $skip, $refusals->refusedOrigins($playerId));
 86	        if ($selection === null) {
 87	            return null;
 88	        }
 89	        [$origin, $target] = $selection;
 90	
 91	        return app()->makeWith(QueueableSpy::class, [
 92	            'planetId' => $origin->getPlanetId(),
 93	            'targetGalaxy' => (int) $target->galaxy,
 94	            'targetSystem' => (int) $target->system,
 95	            'targetPosition' => (int) $target->planet,
 96	            'targetType' => (int) $target->planet_type,
 97	            'missionType' => EspionageMission::getTypeId(),
 98	            'probeCount' => $this->probeCount($target),
 99	        ]);
100	    }
101	
102	    /**
103	     * Every own planet whose idle probes still exceed what its own pending spy intents
104	     * have committed (N6). A probe already promised to a queued or retried intent is not a
105	     * second probe, so two pending probes for different targets each plan from the budget
106	     * that remains after the other is committed.
107	     *
108	     * @return list<PlanetService>
109	     */
110	    private function idleProbePlanets(PlayerService $player): array
111	    {
112	        $committed = $this->committedProbesByPlanet($player->getId());
113	        $probeName = EspionageMission::getRequiredShipMachineNames()[0];
114	        $planets = [];
115	
116	        foreach ($player->planets->all() as $planet) {
117	            $idle = $planet->getShipUnits()->getAmountByMachineName($probeName);
118	
119	            if ($idle > ($committed[$planet->getPlanetId()] ?? 0)) {
120	                $planets[] = $planet;
121	            }
122	        }
123	
124	        return $planets;
125	    }
126	
127	    /** @return array<int, int> probes committed to open spy intents, keyed by the origin planet */
128	    private function committedProbesByPlanet(int $playerId): array
129	    {
130	        $committed = [];
131	
132	        foreach (AiWorkItem::query()
133	            ->where('player_id', $playerId)
134	            ->where('kind', AiWorkKind::Spy)
135	            ->whereIn('state', [AiWorkState::Pending, AiWorkState::Leased, AiWorkState::Retry])
136	            ->get(['payload']) as $item) {
137	            $payload = $item->payload ?? [];
138	            $planetId = (int) ($payload['planet_id'] ?? 0);
139	
140	            if ($planetId > 0) {
141	                $committed[$planetId] = ($committed[$planetId] ?? 0) + 1;
142	            }
143	        }
144	
145	        return $committed;
146	    }
147	
148	    /**
149	     * The best legal foreign target, scored instead of the first one in id order.
150	     *
151	     * Own, destroyed, vacationing and administrator-protected planets are all
152	     * skipped — the module restates no rule, it only declines candidates the
153	     * host's own mission would refuse. A planet the account already knows, or
154	     * already has a probe travelling toward, is skipped too. Among what remains,
155	     * a just-touched target is skipped (INT-009) and the rest are ranked by
156	     * known yield, what the target paid before and closeness (INT-003): the
157	     * closest known-rich neighbour, not the lowest id.
158	     *
159	     * @param array<string, true> $skipCoordinates
160	     * @param array<int, true> $refusedOrigins own bodies the gate just refused a dispatch from
161	     * @return array{0: PlanetService, 1: Planet}|null the origin and its target
162	     */
163	    private function target(PlayerService $player, array $skipCoordinates, array $refusedOrigins): ?array
164	    {
165	        $idleOrigins = array_values(array_filter(
166	            $this->idleProbePlanets($player),
167	            static fn (PlanetService $planet): bool => ! isset($refusedOrigins[$planet->getPlanetId()]),
168	        ));
169	        if ($idleOrigins === []) {
170	            return null;
171	        }
172	
173	        // A scout reads the neighbours nearest to home, not the oldest stamps in the universe: ordering by the
174	        // owner's last login pushed every cohort account (whose stamp is zero) behind the fixed farms, so
175	        // the nearest rivals were never read and nothing defended was ever raided. The farm-first ranking
176	        // below still picks the quiet body among the nearest, and the host's isInactive() stays the authority.
177	        $home = $idleOrigins[0]->getPlanetCoordinates();
178	        $candidates = Planet::query()
179	            ->leftJoin('users', 'users.id', '=', 'planets.user_id')
180	            ->where('planets.user_id', '!=', $player->getId())
181	            ->where('planets.destroyed', 0)
182	            ->where(fn ($owner) => $owner->whereNull('users.vacation_mode')->orWhere('users.vacation_mode', 0))
183	            ->whereIn('planets.planet_type', [PlanetType::Planet->value, PlanetType::Moon->value])
184	            ->select('planets.*')
185	            ->orderByRaw('ABS(CAST(`planets`.`galaxy` AS SIGNED) - ?) * 100000 + ABS(CAST(`planets`.`system` AS SIGNED) - ?) * 20 + ABS(CAST(`planets`.`planet` AS SIGNED) - ?), `planets`.`id`', [$home->galaxy, $home->system, $home->position])
186	            ->cursor()
187	            ->reject(static fn (Planet $planet): bool => isset($skipCoordinates["{$planet->galaxy}:{$planet->system}:{$planet->planet}"]))
188	            ->take(self::MAX_CANDIDATES)
189	            ->values();
190	
191	        $intel = $this->knownIntelByCoordinate($candidates);
192	        $knownYield = $intel['yield'];
193	        // What the account remembers about these planets: the priority counter, read in one pass so a
194	        // target that paid before is not priced once per candidate.
195	        $priorities = $this->intelBook->priorities($player->getId());
196	        $payoffWeight = $this->intelBook->priorityWeight();
197	        $fighter = $this->ownsWarFleet($idleOrigins);
198	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
199	        $scored = [];
200	
201	        foreach ($candidates as $planet) {
202	            $coordinateKey = "{$planet->galaxy}:{$planet->system}:{$planet->planet}";
203	            if (isset($skipCoordinates[$coordinateKey])) {
204	                continue;
205	            }
206	
207	            // The candidate model is already in hand; building a PlanetService
208	            // from it skips the per-candidate Planet::find + refreshUser that
209	            // make($id, true) would pay (20 candidates × 2 round trips).
210	            $target = $this->planetServiceFactory->makeFromModel($planet);
211	
212	            $owner = $target->getPlayer();
213	
214	            // The host's own protected-administrator signal, so the rule survives any operator rename.
215	            if ($owner?->isAdmin() === true) {
216	                continue;
217	            }
218	            $origin = $this->closestOrigin($player, $idleOrigins, $planet, $fleetMissions);
219	            if ($origin === null) {
220	                continue;
221	            }
222	            $distance = $fleetMissions->calculateFleetMissionDistance($origin, new Coordinate((int) $planet->galaxy, (int) $planet->system, (int) $planet->planet));
223	            $scored[] = [
224	                'planet' => $planet,
225	                'origin' => $origin,
226	                'inactive' => $owner?->isInactive() ?? false,
227	                'quiet' => !$this->activityIntelReader->activityAt($target),
228	                'defended' => $fighter && isset($intel['defended'][$coordinateKey]),
229	                'score' => ($knownYield[$coordinateKey] ?? 0.0) - $distance + $payoffWeight * ($priorities[$coordinateKey] ?? 0),
230	            ];
231	        }
232	
233	        if ($scored === []) {
234	            return null;
235	        }
236	
237	        // The farm comes first, then the neighbour away from the keyboard, then the one at it: a player who
238	        // has read every quiet body still scouts the active ones, since an account that acts every few
239	        // minutes is the only kind that fights back and leaves debris. Among equals the closest known-rich
240	        // body wins (INT-003).
241	        // An account that owns a war fleet reads the bodies known to fight back first: an administrator
242	        // sees raids that pillage empty planets as a dead universe (LIFE_FIGHTS), and a fleet is built
243	        // to be flown at something that shoots.
244	        usort($scored, static fn (array $left, array $right): int => [$right['defended'], $right['inactive'], $right['quiet'], $right['score']] <=> [$left['defended'], $left['inactive'], $left['quiet'], $left['score']]);
245	
246	        return [$scored[0]['origin'], $scored[0]['planet']];
247	    }
248	
249	    /**
250	     * Whether any scouting base stands a military hull, by the host's own military catalogue.
251	     *
252	     * @param list<PlanetService> $origins
253	     */
254	    private function ownsWarFleet(array $origins): bool
255	    {
256	        $military = array_map(static fn ($ship): string => $ship->machine_name, ObjectService::getMilitaryShipObjects());
257	
258	        foreach ($origins as $origin) {
259	            foreach ($origin->getShipUnits()->units as $entry) {
260	                // A probe is in the military catalogue but carries no real weapon: a war fleet shoots.
261	                $player = $origin->getPlayer();
262	                if ($player !== null && in_array($entry->unitObject->machine_name, $military, true) && $entry->unitObject->properties->attack->calculate($player)->totalValue > 1) {
263	                    return true;
264	                }
265	            }
266	        }
267	
268	        return false;
269	    }
270	
271	    /**
272	     * The own planet with an idle probe closest to the target that can pay the flight, not the first in
273	     * collection order: a probe is fuel and time, so the nearest base that has the deuterium sends it.
274	     * No such base means the target is not scouted now, as a player with an empty tank does not queue it.
275	     *
276	     * @param list<PlanetService> $origins
277	     */
278	    private function closestOrigin(PlayerService $player, array $origins, Planet $target, FleetMissionService $fleetMissions): PlanetService|null
279	    {
280	        $coordinate = new Coordinate((int) $target->galaxy, (int) $target->system, (int) $target->planet);
281	        $probe = ObjectService::getUnitObjectByMachineName(EspionageMission::getRequiredShipMachineNames()[0]);
282	        $best = null;
283	        $bestDistance = null;
284	
285	        foreach ($origins as $origin) {
286	            $units = new UnitCollection();
287	            $units->addUnit($probe, $this->probeCount($target));
288	            if (!app(FlightFuel::class)->affordable($player, $origin, $units, $coordinate, 10)) {
289	                continue;
290	            }
291	            $distance = $fleetMissions->calculateFleetMissionDistance($origin, $coordinate);
292	            if ($bestDistance === null || $distance < $bestDistance) {
293	                $best = $origin;
294	                $bestDistance = $distance;
295	            }
296	        }
297	
298	        return $best;
299	    }
300	
301	    /**
302	     * The probes this target is worth. A complete report refreshes with one; a
303	     * partial report on a defended or known-rich body gets a volley — the host
304	     * redacts ships below two probes and defence below three, so one probe is
305	     * how the account keeps re-reading the same redacted report forever. An
306	     * empty redaction stays at one: the probes are not worth it.
307	     */
308	    private function probeCount(Planet $target): int
309	    {
310	        $report = EspionageReport::query()
311	            ->where('planet_galaxy', $target->galaxy)
312	            ->where('planet_system', $target->system)
313	            ->where('planet_position', $target->planet)
314	            ->orderByDesc('id')
315	            ->first(['resources', 'ships', 'defense']);
316	
317	        if ($report === null) {
318	            return 1;
319	        }
320	
321	        if ($this->activityIntelReader->completenessFactor($report->ships, $report->defense) >= 1.0) {
322	            return 1;
323	        }
324	
325	        if (!$this->isDefended($report->ships, $report->defense) && $this->yieldFromResources($report->resources ?? []) < self::RICH_YIELD) {
326	            return 1;
327	        }
328	
329	        return self::ESCALATED_PROBES;
330	    }
331	
332	    /**
333	     * @param array<string, int>|null $ships
334	     * @param array<string, int>|null $defense
335	     */
336	    private function isDefended(array|null $ships, array|null $defense): bool
337	    {
338	        return ($ships ?? []) !== [] || ($defense ?? []) !== [];
339	    }
340	
341	    /**
342	     * The last-known loot of each candidate, as metal-equivalent, from its most
343	     * recent report of any age. A never-probed planet scores zero here and is
344	     * ranked by closeness alone.
345	     *
346	     * Also says which of them the last report found defended (ships or defence standing), since the
347	     * scout that owns a war fleet reads the bodies that fight before the empty farms.
348	     *
349	     * @param iterable<int, Planet> $candidates
350	     * @return array{yield: array<string, float>, defended: array<string, true>}
351	     */
352	    private function knownIntelByCoordinate(iterable $candidates): array
353	    {
354	        $planets = is_array($candidates) ? $candidates : iterator_to_array($candidates);
355	        if ($planets === []) {
356	            return ['yield' => [], 'defended' => []];
357	        }
358	
359	        // One pass over the candidate coordinates instead of one report read per
360	        // candidate: the newest report per coordinate wins, so keep the first
361	        // (highest id) seen on the descending-id sweep.
362	        $reports = EspionageReport::query()
363	            ->where(function ($query) use ($planets): void {
364	                foreach ($planets as $planet) {
365	                    $query->orWhere(function ($coordinate) use ($planet): void {
366	                        $coordinate->where('planet_galaxy', $planet->galaxy)
367	                            ->where('planet_system', $planet->system)
368	                            ->where('planet_position', $planet->planet);
369	                    });
370	                }
371	            })
372	            ->orderByDesc('id')
373	            ->get(['id', 'planet_galaxy', 'planet_system', 'planet_position', 'resources', 'ships', 'defense']);
374	
375	        $yield = [];
376	        $defended = [];
377	        foreach ($reports as $report) {
378	            $key = "{$report->planet_galaxy}:{$report->planet_system}:{$report->planet_position}";
379	            if (isset($yield[$key])) {
380	                continue;
381	            }
382	
383	            $yield[$key] = $this->yieldFromResources($report->resources ?? []);
384	            if ($this->isDefended($report->ships, $report->defense)) {
385	                $defended[$key] = true;
386	            }
387	        }
388	
389	        return ['yield' => $yield, 'defended' => $defended];
390	    }
391	
392	    /**
393	     * Metal-equivalent of a report's visible resources, on the estimator's own weights.
394	     *
395	     * @param array<string, mixed> $resources
396	     */
397	    private function yieldFromResources(array $resources): float
398	    {
399	        return (float) ($resources['metal'] ?? 0)
400	            + 1.5 * (float) ($resources['crystal'] ?? 0)
401	            + 2.0 * (float) ($resources['deuterium'] ?? 0);
402	    }
403	
404	    /**
405	     * The coordinates the account already holds fresh intel on, keyed g:s:p.
406	     *
407	     * A report is reached through the account's own messages, the host's link
408	     * from a probe to the report it produced, and only reports inside the intel
409	     * window count. The window matches the observation service's TTL so scouting
410	     * and raiding agree on what "recently probed" means.
411	     *
412	     * @return array<string, true>
413	     */
414	    private function freshIntelCoordinates(int $playerId): array
415	    {
416	        $reportIds = Message::query()
417	            ->where('user_id', $playerId)
418	            ->whereNotNull('espionage_report_id')
419	            ->where('created_at', '>=', now()->subHours(self::INTEL_TTL_HOURS))
420	            ->pluck('espionage_report_id');
421	
422	        $coordinates = [];
423	        foreach (EspionageReport::query()->whereIn('id', $reportIds)->get(['planet_galaxy', 'planet_system', 'planet_position']) as $report) {
424	            $coordinates["{$report->planet_galaxy}:{$report->planet_system}:{$report->planet_position}"] = true;
425	        }
426	
427	        return $coordinates;
428	    }
429	
430	    /**
431	     * The coordinates this account already has an espionage probe travelling to,
432	     * keyed g:s:p. A probe that has not returned yet yields no report, so it has
433	     * to be skipped on its own signal rather than through fresh intel: firing a
434	     * second probe at the same planet before the first is back is the other half
435	     * of the re-probing loop the freshness guard alone cannot stop.
436	     *
437	     * @return array<string, true>
438	     */
439	    private function inFlightCoordinates(int $playerId): array
440	    {
441	        $coordinates = [];
442	        foreach (FleetMission::query()
443	            ->where('user_id', $playerId)
444	            ->where('mission_type', EspionageMission::getTypeId())
445	            ->where('processed', 0)
446	            ->where('canceled', 0)
447	            ->get(['galaxy_to', 'system_to', 'position_to']) as $mission) {
448	            $coordinates["{$mission->galaxy_to}:{$mission->system_to}:{$mission->position_to}"] = true;
449	        }
450	
451	        return $coordinates;
452	    }
453	
454	    /**
455	     * The coordinates this account has already decided to probe but not yet
456	     * dispatched, keyed g:s:p. A queued or retried intent sits between the
457	     * decision and the mission, and a report does not exist for it yet, so it
458	     * has to be skipped on its own signal: deciding to probe the same target
459	     * again every session while the earlier intent is still waiting is the
460	     * third leg of the re-probing loop, after fresh intel and the in-flight
461	     * mission.
462	     *
463	     * @return array<string, true>
464	     */
465	    private function openSpyIntentCoordinates(int $playerId): array
466	    {
467	        $coordinates = [];
468	        foreach (AiWorkItem::query()
469	            ->where('player_id', $playerId)
470	            ->where('kind', AiWorkKind::Spy)
471	            ->whereIn('state', [AiWorkState::Pending, AiWorkState::Leased, AiWorkState::Retry])
472	            ->get(['payload']) as $item) {
473	            $payload = $item->payload ?? [];
474	            if (isset($payload['target_galaxy'], $payload['target_system'], $payload['target_position'])) {
475	                $coordinates["{$payload['target_galaxy']}:{$payload['target_system']}:{$payload['target_position']}"] = true;
476	            }
477	        }
478	
479	        return $coordinates;
480	    }
481	}

  200	        // expires so a queue retry or the scheduler can finish the work instead of the
  201	        // item staying stuck forever.
  202	        return $workItem->state === AiWorkState::Leased
  203	            && $workItem->lease_until !== null
  204	            && $workItem->lease_until->isPast();
  205	    }
