  207	    private function runClaimedSession(AiProfile $profile, AiWorkItem $workItem, string $leaseToken): void
  208	    {
  209	        app(RunAiSession::class)->handle($profile, $workItem);
  210	        $this->completeLease($workItem, $leaseToken);
  211	    }
  212	
  213	    private function queueClaimedIntent(AiProfile $profile, AiWorkItem $workItem, string $leaseToken): void
  214	    {
  215	        // The action cap bounds what a session may touch, not what it may think: at zero the
  216	        // session already decided and scheduled, so this pass closes its lease and acts on
  217	        // nothing.
  218	        if (!app(ResolveAiAdmissionAction::class)->forAction()->allowed) {
  219	            $this->completeLease($workItem, $leaseToken);
  220	
  221	            return;
  222	        }
  223	
  224	        // A decision is written before it flies and the worker may run it hours later, so a refusal the
  225	        // gate raised in between is one no planner could have read. The account does not ask again what it
  226	        // was already told: an intent naming a refused body or target is dropped, and the refusal stays
  227	        // the one receipt instead of one per queued decision (DISPATCH_REFUSALS).
  228	        if ($this->repeatsRefusal($workItem)) {
  229	            $this->completeLease($workItem, $leaseToken);
  230	
  231	            return;
  232	        }
  233	
  234	        $receipt = AiActionReceipt::query()->firstOrCreate(
  235	            ['idempotency_key' => $workItem->idempotency_key],
  236	            [
  237	                'player_id' => $workItem->player_id,
  238	                'action_type' => $workItem->kind->actionType(),
  239	                'state' => AiReceiptState::Processing,
  240	            ],
  241	        );
  242	        if (in_array($receipt->state, [AiReceiptState::Accepted, AiReceiptState::Completed, AiReceiptState::Rejected], true)) {
  243	            $this->completeLease($workItem, $leaseToken);
  244	
  245	            return;
  246	        }
  247	
  248	        $planetId = $this->ownedPlanetIdFor($workItem);
  249	        if ($planetId === 0) {
  250	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::NoOwnedPlanet->value]]);
  251	            $this->completeLease($workItem, $leaseToken);
  252	
  253	            return;
