154	    /**
155	     * @return array{0: AiActionResult|null, 1: array<string, mixed>, 2: int}
156	     */
157	    private function build(AiWorkItem $workItem, int $planetId): array
158	    {
159	        $buildingId = $workItem->payload[self::PAYLOAD_BUILDING_ID] ?? null;
160	        // An order planned earlier binds a building to a planet; if the queue filled or the yard went
161	        // busy since, the host refuses it and the account repeats the same refusal. Plan it again.
162	        if (is_int($buildingId) && app(QueueableBuildingPlanner::class)->orderIsStale($workItem->player_id, $planetId, $buildingId)) {
163	            $buildingId = null;
164	        }
165	        $step = is_int($buildingId)
166	            ? app()->makeWith(QueueableBuilding::class, [
167	                'planetId' => $planetId,
168	                'buildingId' => $buildingId,
169	                'reason' => $this->reason($workItem),
170	            ])
171	            : $this->plannedBuild($workItem->player_id);
172	
173	        if (!$step instanceof QueueableBuilding) {
174	            return [null, [], 0];
175	        }
176	
177	        return [
178	            app(QueueAiBuilding::class)->handle($workItem->player_id, $step->planetId, $step->buildingId),
179	            ['building_id' => $step->buildingId, 'build_reason' => $step->reason],
180	            $step->planetId,
181	        ];
182	    }
