 26	/**
 27	 * Whether this account should ferry resources from one of its bodies to another, and which.
 28	 *
 29	 * A colony that cannot pay for its next level waits on the homeworld's surplus; a player looks at
 30	 * what the colony wants to build next, subtracts what is already on it and already flying to it, and
 31	 * ships the difference from the planet that can spare it without starving itself (E4/X1). The
 32	 * shortfall is netted against in-flight transports so one hole is never funded twice, the source must
 33	 * keep its reserve (SP5), and a shipment below the ordinary minimum is not worth the fleet's time.
 34	 *
 35	 * Nothing here names a game object. What a planet wants next is the same host-quoted step the
 36	 * economy planner asks -- storage overflow, energy, the facility chain, then the best mine -- and its
 37	 * price is the host's price, so an extension that adds a build or a resource changes the ferry with
 38	 * no module edit.
 39	 */
 40	class QueueableTransferPlanner
 41	{
 42	    /**
 43	     * r4fek's documented floor: combined metal and crystal below this is not worth a shipment.
 44	     * Shared with the dispatch adapter, which re-applies it to the clamped amount rather than
 45	     * flying a fleet for what is left of a spent surplus.
 46	     */
 47	    public const MINIMUM_SHIPMENT = 50_000;
 48	
 49	    /** A planet at this fraction of its storage is about to overflow and is swept (E9). */
 50	    private const SURPLUS_RATIO = 0.8;
 51	
 52	    public function __construct(
 53	        private PlayerServiceFactory $playerServiceFactory,
 54	        private PlanetServiceFactory $planetServiceFactory,
 55	        private EconomyUpgrades $economyUpgrades,
 56	        private EnergyCapacity $energyCapacity,
 57	        private FacilityChain $facilityChain,
 58	        private DefenseNeedEvaluator $defenseNeed,
 59	        private ReserveFloor $reserveFloor,
 60	        private QueueAiTransferAction $transferAction,
 61	        private AllyGiftGuard $giftGuard,
 62	    ) {
 63	    }
 64	
 65	    public function plan(int $playerId): ?QueueableTransfer
 66	    {
 67	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 68	        if ($profile === null) {
 69	            return null;
 70	        }
 71	
 72	        if (!User::query()->whereKey($playerId)->exists()) {
 73	            return null;
 74	        }
 75	
 76	        // A player does not load the same hulls twice: a ferry still waiting to fly holds the cargo
 77	        // ships, so a second one offered now fails at dispatch with no transport fleet.
 78	        if ($this->transferWaiting($playerId)) {
 79	            return null;
 80	        }
 81	
 82	        $player = $this->playerServiceFactory->make($playerId, true);
 83	        $planets = $player->planets->all();
 84	        if (count($planets) < 2) {
 85	            return null;
 86	        }
 87	
 88	        // A source the gate just refused is not a source this login offers again: a refused dispatch is
 89	        // not a mission, so nothing else recorded the empty tank or the missing hull.
 90	        $refusedOrigins = app(RecentRefusals::class)->refusedOrigins($playerId);
 91	
 92	        foreach ($planets as $planet) {
 93	            $planet->updateResources(false);
 94	            $planet->updateResourceProductionStats(false);
 95	            $planet->updateResourceStorageStats(false);
 96	        }
 97	
 98	        foreach ($planets as $target) {
 99	            $wallNeed = $this->wallNeed($target, $planets, $playerId);
100	            $need = $wallNeed ?? $this->need($target, $profile, $playerId);
101	            if ($need === null || ($wallNeed === null && !$this->worthShipping($need))) {
102	                continue;
103	            }
104	
105	            $source = $this->source($planets, $target, $need, $player, $refusedOrigins);
106	            if ($source === null) {
107	                continue;
108	            }
109	
110	            return app()->makeWith(QueueableTransfer::class, [
111	                'sourcePlanetId' => $source->getPlanetId(),
112	                'targetPlanetId' => $target->getPlanetId(),
113	                'metal' => (int) round($need->metal->get()),
114	                'crystal' => (int) round($need->crystal->get()),
115	                'deuterium' => (int) round($need->deuterium->get()),
116	            ]);
117	        }
118	
119	        return $this->surplus($planets, $player, $refusedOrigins) ?? $this->allyGift($planets, $player, $playerId, $refusedOrigins);
120	    }
