122	    /**
123	     * The ferry an inbound asks for: the pile a threatened body cannot keep leaves for a sibling the
124	     * same attack is not aimed at (D6). A player whose planet is about to be hit loads the hulls he is
125	     * keeping at home and moves what the raider would otherwise carry off; the fleet that is worth the
126	     * trip is already leaving, and this is the stock it leaves behind.
127	     *
128	     * The shipment is the same above-floor sweep the surplus ferry flies, so the body keeps its own
129	     * economy running while the pile goes, and the hold, the fuel and the target legality stay the
130	     * dispatch adapter's questions: a pile bigger than the holds is loaded as far as the holds go.
131	     *
132	     * Null when there is nothing above the body's reserve, no sibling out of the attack's reach, or no
133	     * hull on the body to carry it -- the account keeps what it cannot move.
134	     *
135	     * @param list<int> $threatenedPlanetIds the own bodies this attack is aimed at, none of which may receive
136	     */
137	    public function evacuationPlan(int $playerId, int $planetId, array $threatenedPlanetIds): ?QueueableTransfer
138	    {
139	        $player = $this->playerServiceFactory->make($playerId, true);
140	        $planets = $player->planets->all();
141	
142	        // A body the gate just refused a dispatch from cannot launch, so the pile stays where it is and
143	        // offering the move again only repeats the refusal.
144	        if (isset(app(RecentRefusals::class)->refusedOrigins($playerId)[$planetId])) {
145	            return null;
146	        }
147	
148	        $source = null;
149	        foreach ($planets as $planet) {
150	            if ($planet->getPlanetId() === $planetId) {
151	                $source = $planet;
152	            }
153	        }
154	
155	        if ($source === null) {
156	            return null;
157	        }
158	
159	        $source->updateResources(false);
160	        if (! $this->hasCargo($source, $player)) {
161	            return null;
162	        }
163	
164	        $shipment = $this->aboveFloor($source, $this->reserveFloor->floor($source, ReserveFloor::ECONOMY_HOURS), false);
165	        if (! $this->worthShipping($shipment)) {
166	            return null;
167	        }
168	
169	        foreach ($planets as $target) {
170	            if ($target->getPlanetId() === $planetId || in_array($target->getPlanetId(), $threatenedPlanetIds, true)) {
171	                continue;
172	            }
173	
174	            if (! $this->canPayFuel($source, $target, $shipment, $player)) {
175	                continue;
176	            }
177	
178	            return app()->makeWith(QueueableTransfer::class, [
179	                'sourcePlanetId' => $source->getPlanetId(),
180	                'targetPlanetId' => $target->getPlanetId(),
181	                'metal' => (int) round($shipment->metal->get()),
182	                'crystal' => (int) round($shipment->crystal->get()),
183	                'deuterium' => (int) round($shipment->deuterium->get()),
184	            ]);
185	        }
186	
187	        return null;
188	    }
