190	    /** How long after seeing an ally attacked a gift is still offered. */
191	    private const ALLY_GIFT_WINDOW_HOURS = 6;
192	
193	    /**
194	     * A tenth of what the richest body holds, sent to an alliance co-member just seen attacked
195	     * (IMPL-71): a player helps an ally rebuild after a raid. Nothing leaves unless AllyGiftGuard
196	     * passes the exact shipment, so the planner never offers what the adapter would refuse.
197	     *
198	     * @param array<PlanetService> $planets
199	     * @param array<int, true> $refusedOrigins own bodies the gate just refused a dispatch from
200	     */
201	    private function allyGift(array $planets, PlayerService $player, int $playerId, array $refusedOrigins): ?QueueableTransfer
202	    {
203	        $reports = AiObservation::query()
204	            ->where('player_id', $playerId)
205	            ->where('kind', AiObservationKind::AllyUnderAttack)
206	            ->where('observed_at', '>=', now()->subHours(self::ALLY_GIFT_WINDOW_HOURS))
207	            ->orderByDesc('observed_at')
208	            ->pluck('source_id');
209	
210	        foreach ($reports as $reportId) {
211	            $allyId = BattleReport::query()->whereKey($reportId)->value('planet_user_id');
212	            $targetId = $allyId === null ? null : Planet::query()->where('user_id', $allyId)->orderBy('id')->value('id');
213	            if ($targetId === null) {
214	                continue;
215	            }
216	
217	            foreach ($planets as $source) {
218	                if (isset($refusedOrigins[$source->getPlanetId()])) {
219	                    continue;
220	                }
221	
222	                $floor = $this->reserveFloor->floor($source, ReserveFloor::ECONOMY_HOURS);
223	                $share = AllyGiftGuard::MAX_STOCK_SHARE;
224	                $gift = new Resources(
225	                    floor(min($source->metal()->get() * $share, max(0.0, $source->metal()->get() - $floor->metal->get()))),
226	                    floor(min($source->crystal()->get() * $share, max(0.0, $source->crystal()->get() - $floor->crystal->get()))),
227	                    0.0,
228	                );
229	                if ($gift->sum() <= 0 || !$this->hasCargo($source, $player)) {
230	                    continue;
231	                }
232	                if ($this->giftGuard->refusal(
233	                    $playerId,
234	                    (int) $targetId,
235	                    (int) $gift->metal->get(),
236	                    (int) $gift->crystal->get(),
237	                    0,
238	                    $source->metal()->get(),
239	                    $source->crystal()->get(),
240	                    $source->deuterium()->get(),
241	                ) !== null) {
242	                    continue 2;
243	                }
244	                $targetPlanet = $this->planetServiceFactory->make((int) $targetId, true);
245	                if ($targetPlanet === null || !$this->canPayFuel($source, $targetPlanet, $gift, $player)) {
246	                    continue;
247	                }
248	
249	                return app()->makeWith(QueueableTransfer::class, [
250	                    'sourcePlanetId' => $source->getPlanetId(),
251	                    'targetPlanetId' => (int) $targetId,
252	                    'metal' => (int) $gift->metal->get(),
253	                    'crystal' => (int) $gift->crystal->get(),
254	                    'deuterium' => 0,
255	                ]);
256	            }
257	        }
258	
259	        return null;
260	    }
