262	    /**
263	     * A ferry that has already loaded the hulls keeps them until it flies, so a second one would
264	     * fail at dispatch with no transport fleet. Only an intent that names its shipment is on the
265	     * pad: the re-plan arm runs while the account's own intent carries no payload to read, and
266	     * counting that one would refuse every re-plan of the intent it is executing.
267	     */
268	    private function transferWaiting(int $playerId): bool
269	    {
270	        return AiWorkItem::query()
271	            ->where('player_id', $playerId)
272	            ->where('kind', AiWorkKind::Transfer)
273	            ->whereIn('state', [AiWorkState::Pending, AiWorkState::Retry, AiWorkState::Leased])
274	            ->get(['payload'])
275	            ->contains(static fn (AiWorkItem $item): bool => isset($item->payload['source_planet_id']));
