278	    /**
279	     * The reverse of the need-driven ferry: a planet about to overflow ships its
280	     * above-floor surplus to the best-developed body, so the mines do not stall
281	     * (E9/X2). A moon keeps its deuterium for fleet jumps; a planet sweeps all
282	     * three resources.
283	     *
284	     * @param array<PlanetService> $planets
285	     * @param array<int, true> $refusedOrigins own bodies the gate just refused a dispatch from
286	     */
287	    private function surplus(array $planets, PlayerService $player, array $refusedOrigins): ?QueueableTransfer
288	    {
289	        $drop = $this->dropBody($planets);
290	        if ($drop === null) {
291	            return null;
292	        }
293	
294	        foreach ($planets as $source) {
295	            if ($source->getPlanetId() === $drop->getPlanetId() || isset($refusedOrigins[$source->getPlanetId()]) || !$this->nearCap($source)) {
296	                continue;
297	            }
298	
299	            $floor = $this->reserveFloor->floor($source, ReserveFloor::ECONOMY_HOURS);
300	            $shipment = $this->aboveFloor($source, $floor, $source->getPlanetType() === PlanetType::Moon);
301	            if (!$this->worthShipping($shipment) || !$this->hasCargo($source, $player) || !$this->canPayFuel($source, $drop, $shipment, $player)) {
302	                continue;
303	            }
304	
305	            return app()->makeWith(QueueableTransfer::class, [
306	                'sourcePlanetId' => $source->getPlanetId(),
307	                'targetPlanetId' => $drop->getPlanetId(),
308	                'metal' => (int) round($shipment->metal->get()),
309	                'crystal' => (int) round($shipment->crystal->get()),
310	                'deuterium' => (int) round($shipment->deuterium->get()),
311	            ]);
312	        }
313	
314	        return null;
315	    }
316	
317	    /**
318	     * The most developed own planet, by the host's building count: the drop the
319	     * surplus consolidates onto. Moons are never the drop.
320	     *
321	     * @param array<PlanetService> $planets
322	     */
323	    private function dropBody(array $planets): ?PlanetService
324	    {
325	        $best = null;
326	        foreach ($planets as $planet) {
327	            if ($planet->getPlanetType() === PlanetType::Moon) {
328	                continue;
329	            }
330	
331	            if ($best === null || $planet->getBuildingCount() > $best->getBuildingCount()) {
332	                $best = $planet;
333	            }
334	        }
335	
336	        return $best;
337	    }
