339	    /** Whether either stored resource is at or past the near-cap threshold. */
340	    private function nearCap(PlanetService $planet): bool
341	    {
342	        return $planet->metal()->get() >= self::SURPLUS_RATIO * $planet->metalStorage()->get()
343	            || $planet->crystal()->get() >= self::SURPLUS_RATIO * $planet->crystalStorage()->get();
344	    }
