346	    /** What a body ships above its reserve floor; a moon keeps its deuterium. */
347	    private function aboveFloor(PlanetService $source, Resources $floor, bool $keepDeuterium): Resources
348	    {
349	        return new Resources(
350	            max(0.0, $source->metal()->get() - $floor->metal->get()),
351	            max(0.0, $source->crystal()->get() - $floor->crystal->get()),
352	            $keepDeuterium ? 0.0 : max(0.0, $source->deuterium()->get() - $floor->deuterium->get()),
353	        );
354	    }
