356	    /**
357	     * What a bare planet beside a walled sibling is short for the facility its wall waits on, or null.
358	     *
359	     * A player ships the missing few hundred deuterium to the colony that cannot raise its yard: the
360	     * shipment floor protects the fleet's time, but a planet stuck below one cheap step stays naked
361	     * for good without the ferry (measured live 3 Oct 2026: 22k metal, 116 deuterium, no robotics).
362	     *
363	     * @param array<PlanetService> $planets
364	     */
365	    private function wallNeed(PlanetService $target, array $planets, int $playerId): ?Resources
366	    {
367	        if ($this->defenseNeed->standingUnits($target) > 0) {
368	            return null;
369	        }
370	
371	        $siblingWalled = array_filter($planets, fn (PlanetService $planet): bool => $this->defenseNeed->standingUnits($planet) > 0);
372	        if ($siblingWalled === []) {
373	            return null;
374	        }
375	
376	        // The first facility the planet cannot pay for is what keeps it bare; one it can pay for it builds itself.
377	        $inFlight = $this->inFlightTo($target, $playerId);
378	        foreach ($this->facilityChain->wallPending($target) as $step) {
379	            $price = ObjectService::getObjectPrice(ObjectService::getObjectById($step->buildingId)->machine_name, $target);
380	            $need = new Resources(
381	                max(0.0, $price->metal->get() - $target->metal()->get() - $inFlight->metal->get()),
382	                max(0.0, $price->crystal->get() - $target->crystal()->get() - $inFlight->crystal->get()),
383	                max(0.0, $price->deuterium->get() - $target->deuterium()->get() - $inFlight->deuterium->get()),
384	            );
385	            if ($need->sum() > 0) {
386	                return $need;
387	            }
388	        }
389	
390	        return null;
391	    }
