393	    /**
394	     * What this planet is short for its next level: its price minus what is already there and already
395	     * flying to it, floored at zero so a planet that has enough ships nothing.
396	     */
397	    private function need(PlanetService $target, AiProfile $profile, int $playerId): ?Resources
398	    {
399	        $price = $this->nextStepPrice($target, $profile);
400	        if ($price === null) {
401	            return null;
402	        }
403	
404	        $inFlight = $this->inFlightTo($target, $playerId);
405	
406	        return new Resources(
407	            max(0.0, $price->metal->get() - $target->metal()->get() - $inFlight->metal->get()),
408	            max(0.0, $price->crystal->get() - $target->crystal()->get() - $inFlight->crystal->get()),
409	            max(0.0, $price->deuterium->get() - $target->deuterium()->get() - $inFlight->deuterium->get()),
410	        );
411	    }
412	
413	    /**
414	     * The next level this planet wants, in the same order the economy planner takes: storage that is
415	     * about to overflow, energy before the throttle, the chain's facilities, then the best mine.
416	     */
417	    private function nextStepPrice(PlanetService $planet, AiProfile $profile): ?Resources
418	    {
419	        $candidates = [
420	            ...$this->economyUpgrades->storage($planet, $profile),
421	            ...$this->energyCapacity->pending($planet),
422	            ...$this->facilityChain->pending($planet),
423	            ...$this->economyUpgrades->production($planet, $profile),
424	        ];
425	
426	        // The ferry funds the step the planet cannot reach on its own, so a candidate whose whole
427	        // price is below the shipment floor -- a cheap research the planet pays for from an hour of
428	        // income -- is not the shortfall a player ships resources for; the next step down the same
429	        // list is.
430	        foreach ($candidates as $candidate) {
431	            $price = ObjectService::getObjectPrice(ObjectService::getObjectById($candidate->buildingId)->machine_name, $planet);
432	            if ($this->worthShipping($price)) {
433	                return $price;
434	            }
435	        }
436	
437	        return null;
438	    }
439	
440	    /** The account's own transports already on the way to this body, netted off before the shortfall. */
441	    private function inFlightTo(PlanetService $target, int $playerId): Resources
442	    {
443	        $missions = FleetMission::query()
444	            ->where('user_id', $playerId)
445	            ->where('planet_id_to', $target->getPlanetId())
446	            ->where('mission_type', TransportMission::getTypeId())
447	            ->where('processed', 0)
448	            ->where('canceled', 0)
449	            ->where('time_arrival', '>=', now()->timestamp)
450	            ->get(['metal', 'crystal', 'deuterium']);
451	
452	        return new Resources(
453	            (float) $missions->sum('metal'),
454	            (float) $missions->sum('crystal'),
455	            (float) $missions->sum('deuterium'),
456	        );
457	    }
458	
459	    /**
460	     * The first other body that can spare the shipment and still keep its own reserve.
461	     *
462	     * @param array<PlanetService> $planets
463	     * @param array<int, true> $refusedOrigins own bodies the gate just refused a dispatch from
464	     */
465	    private function source(array $planets, PlanetService $target, Resources $need, PlayerService $player, array $refusedOrigins): ?PlanetService
466	    {
467	        foreach ($planets as $source) {
468	            if ($source->getPlanetId() === $target->getPlanetId() || isset($refusedOrigins[$source->getPlanetId()])) {
469	                continue;
470	            }
471	
472	            $floor = $this->reserveFloor->floor($source, ReserveFloor::ECONOMY_HOURS);
473	            // A resource the shipment does not carry keeps no floor: the source only reserves what it
474	            // actually spends, so a metal-and-crystal ferry is not blocked by a deuterium reserve.
475	            $required = new Resources(
476	                $need->metal->get() > 0 ? $need->metal->get() + $floor->metal->get() : 0,
477	                $need->crystal->get() > 0 ? $need->crystal->get() + $floor->crystal->get() : 0,
478	                $need->deuterium->get() > 0 ? $need->deuterium->get() + $floor->deuterium->get() : 0,
479	            );
480	
481	            if ($source->hasResources($required) && $this->hasCargo($source, $player) && $this->canPayFuel($source, $target, $need, $player)) {
482	                return $source;
483	            }
484	        }
485	
486	        return null;
487	    }
488	
489	    /**
490	     * A ferry needs a hull with a hold: a source with no cargo ships can never fly, so the planner
491	     * does not publish that transfer. `ponytail:` asks "any cargo", not "enough" — an under-supplied
492	     * source still refuses at dispatch (`NoTransportFleet`), bounded by the account building cargo;
493	     * the upgrade is comparing `getTotalCargoCapacity` to the shipment here.
494	     */
495	    private function hasCargo(PlanetService $source, PlayerService $player): bool
496	    {
497	        return $source->getShipUnits()->getTotalCargoCapacity($player) > 0;
498	    }
499	
500	    /** The flight burns the source's own deuterium on top of the cargo; a source with empty tanks cannot launch. */
501	    private function canPayFuel(PlanetService $source, PlanetService $target, Resources $need, PlayerService $player): bool
502	    {
503	        $fuel = $this->transferAction->flightFuel($player, $source, $target, $need);
504	
505	        return $fuel !== null && $fuel <= floor($source->deuterium()->get());
506	    }
507	
508	    private function worthShipping(Resources $need): bool
509	    {
510	        return $need->metal->get() + $need->crystal->get() >= self::MINIMUM_SHIPMENT;
511	    }
512	}

