    3	namespace Modules\AI\Jobs;
    4	
    5	use Illuminate\Contracts\Queue\ShouldQueue;
    6	use Illuminate\Foundation\Queue\Queueable;
    7	use Illuminate\Support\Facades\Cache;
    8	use Illuminate\Support\Facades\DB;
    9	use Illuminate\Support\Facades\Log;
   10	use Illuminate\Support\Str;
   11	use Modules\AI\Actions\ExecuteAiIntentAction;
   12	use Modules\AI\Actions\ResolveAiAdmissionAction;
   13	use Modules\AI\Contracts\RunAiSession;
   14	use Modules\AI\Domain\Decision\RecentRefusals;
   15	use Modules\AI\Enums\AiActionReceiptResultKey;
   16	use Modules\AI\Enums\AiActionType;
   17	use Modules\AI\Enums\AiQueueActionReason;
   18	use Modules\AI\Enums\AiQueueName;
