   21	use Modules\AI\Enums\AiWorkState;
   22	use Modules\AI\Domain\Routine\SessionPlanner;
   23	use Modules\AI\Models\AiActionReceipt;
   24	use Modules\AI\Models\AiProfile;
   25	use Modules\AI\Models\AiSchedule;
   26	use Modules\AI\Models\AiWorkItem;
   27	use OGame\Models\Planet;
   28	use Throwable;
   29	
   30	class ProcessAiWork implements ShouldQueue
   31	{
   32	    use Queueable;
   33	
   34	    public int $tries = 3;
   35	
   36	    /** Bounds a poison work item; retryLease() owns the work-item attempt cap. */
   37	    public int $maxExceptions = 3;
   38	
   39	    /**
   40	     * Leave margin below the module's Horizon timeout so a worker is not force-killed
   41	     * mid-decision. The grand run raises both values for hybrid driver contention.
   42	     */
   43	    public int $timeout;
   44	
   45	    private const PAYLOAD_PLANET_ID = 'planet_id';
   46	
   47	    public function __construct(public int $workItemId)
   48	    {
   49	        $this->timeout = max(1, (int) config('ai.horizon.supervisors.supervisor-ai.timeout', 30) - 5);
   50	
   51	        // Deterministic AI work has its own module-owned Horizon lane so AI volume
   52	        // cannot starve the general or fleet lanes.
   53	        $this->onQueue(AiQueueName::Ai->value);
   54	    }
   55	
   56	    /** @return list<string> */
   57	    public function tags(): array
   58	    {
   59	        return ['ai', 'ai:work', 'ai:work-item:' . $this->workItemId];
   60	    }
   61	
   62	    public function failed(Throwable $exception): void
   63	    {
   64	        Log::error('AI work item failed after all queue attempts', [
   65	            'work_item_id' => $this->workItemId,
   66	            'error' => $exception->getMessage(),
   67	        ]);
   68	
   69	        $this->scheduleSessionRecovery();
   70	    }
   71	
   72	    public function handle(): void
   73	    {
   74	        // A switch that is off stops new decisions without discarding the work: the item stays
   75	        // pending and the first pass after it is switched back on picks it up again.
   76	        if (!app(ResolveAiAdmissionAction::class)->forWorkItem()->allowed) {
   77	            return;
   78	        }
   79	
   80	        $leaseToken = (string) Str::uuid();
   81	        // Claim before side effects. Every terminal update checks this token so
   82	        // a slow worker cannot complete work leased again by another worker.
   83	        $workItem = $this->claimDueWork($leaseToken);
   84	
   85	        if ($workItem === null) {
   86	            return;
   87	        }
   88	
   89	        $lock = Cache::lock('ai:player:' . $workItem->player_id, 300);
   90	        if (!$lock->get()) {
   91	            $this->retryContendedLease($workItem, $leaseToken);
   92	
   93	            return;
   94	        }
   95	
   96	        try {
   97	            $profile = AiProfile::query()->where('player_id', $workItem->player_id)->where('enabled', true)->first();
   98	            if ($profile === null) {
   99	                $this->completeLease($workItem, $leaseToken);
  100	
  101	                return;
  102	            }
  103	
  104	            if ($workItem->kind === AiWorkKind::RunSession) {
  105	                $this->runClaimedSession($profile, $workItem, $leaseToken);
  106	
  107	                return;
  108	            }
  109	
  110	            $this->queueClaimedIntent($profile, $workItem, $leaseToken);
  111	        } catch (Throwable $exception) {
  112	            $this->retryLease($workItem, $leaseToken);
  113	
  114	            throw $exception;
  115	        } finally {
  116	            $lock->release();
  117	        }
  118	    }
  119	
  120	    private function claimDueWork(string $leaseToken): AiWorkItem|null
  121	    {
  122	        return DB::transaction(function () use ($leaseToken): AiWorkItem|null {
  123	            /** @var AiWorkItem|null $workItem */
  124	            $workItem = AiWorkItem::query()->lockForUpdate()->find($this->workItemId);
  125	            if ($workItem === null || !$this->isClaimable($workItem) || !$this->dueForAccount($workItem)) {
  126	                return null;
  127	            }
  128	
  129	            $workItem->update([
  130	                'state' => AiWorkState::Leased,
  131	                'lease_token' => $leaseToken,
  132	                'lease_until' => now()->addMinutes(5),
  133	                'attempts' => $workItem->attempts + 1,
  134	            ]);
  135	
  136	            return $workItem->fresh();
  137	        });
  138	    }
  139	
  140	    private function acceleratedSession(AiWorkItem $workItem): bool
  141	    {
  142	        if ($workItem->kind !== AiWorkKind::RunSession || (int) config('ai.population.session_interval_seconds', 0) <= 0) {
  143	            return false;
  144	        }
  145	
  146	        // Acceleration shortens the waits, not the night: a dark-period session keeps its due time.
  147	        $profile = $this->workProfile($workItem);
  148	
  149	        return $profile === null || app(SessionPlanner::class)->isAwake($profile, now()->toImmutable());
  150	    }
