310	    private function liftableStock(PlayerService $player, PlanetService $origin, UnitCollection $fleet, PlanetService $destination, float $speed, FleetMissionService $fleetMissions): Resources
311	    {
312	        // The flight is paid from the planet's deuterium, so only what is left after the fuel (and at most
313	        // half of it) goes into the hold: a hold that took it all leaves the dispatch short of fuel.
314	        $fuel = (float) $fleetMissions->calculateConsumption($origin, $fleet, $destination->getPlanetCoordinates(), 0, $speed);
