320	            return $stock;
321	        }
322	
323	        if ($capacity <= 0) {
324	            return new Resources();
325	        }
326	
327	        // Whole units, rounded down: the host refuses a hold that is full by a fraction.
328	        $share = $capacity / $stock->sum();
329	
330	        return new Resources(
331	            floor($stock->metal->get() * $share),
332	            floor($stock->crystal->get() * $share),
333	            floor($stock->deuterium->get() * $share),
334	        );
