350	            foreach ($units as $entry) {
351	                $candidate->addUnit($entry->unitObject, $entry->amount);
352	            }
353	
354	            $fuel = (float) $fleetMissions->calculateConsumption($origin, $candidate, $destination->getPlanetCoordinates(), 0, $speed);
355	            if ($fuel <= floor($origin->deuterium()->get()) && $fuel <= $candidate->getTotalFuelCapacity($player)) {
356	                return $candidate;
357	            }
358	
359	            $thirstiest = null;
360	            $worst = -1.0;
361	            foreach ($units as $name => $entry) {
