 41	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 42	        }
 43	
 44	        try {
 45	            $player = $this->playerGameStateService->advance($playerId, $sourcePlanetId);
 46	            if ($player->isBanned()) {
 47	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 48	            }
 49	            if ($player->isInVacationMode()) {
 50	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 51	            }
 52	
 53	            $source = $this->planetServiceFactory->makeForPlayer($player, $sourcePlanetId, false);
 54	            $target = $this->planetServiceFactory->make($targetPlanetId, true);
 55	            if ($target === null) {
 56	                return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 57	            }
