 59	            $fleet = $this->heldFleet($source);
 60	            if ($fleet->units === []) {
 61	                return AiActionResult::rejected(AiQueueActionReason::NoDisposableFleet);
 62	            }
 63	
 64	            if (!app(FlightFuel::class)->affordable($player, $source, $fleet, $target->getPlanetCoordinates(), self::SPEED, self::HOLDING_HOURS)) {
 65	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 66	            }
 67	
 68	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
 69	            $mission = $fleetMissions->createNewFromPlanet(
 70	                $source,
 71	                $target->getPlanetCoordinates(),
 72	                $target->getPlanetType(),
 73	                AcsDefendMission::getTypeId(),
 74	                $fleet,
 75	                new Resources(),
 76	                self::SPEED,
 77	                self::HOLDING_HOURS,
 78	            );
 79	
 80	            return AiActionResult::queued($mission->id);
 81	        } catch (Exception $exception) {
 82	            return AiActionResult::rejected($exception->getMessage());
 83	        }
 84	    }
 85	
 86	    /**
 87	     * The hulls a defence sends: half of every combat ship the body holds, so half stays home. The
 88	     * planner quotes this exact fleet, so what it promises is what the gate dispatches.
 89	     */
 90	    public function heldFleet(PlanetService $source): UnitCollection
 91	    {
 92	        $owned = $source->getShipUnits()->toArray();
 93	        $fleet = new UnitCollection();
 94	        foreach (ObjectService::getMilitaryShipObjects() as $ship) {
 95	            $send = intdiv($owned[$ship->machine_name] ?? 0, 2);
 96	            if ($send > 0) {
 97	                $fleet->addUnit($ship, $send);
 98	            }
 99	        }
100	
101	        return $fleet;
102	    }
103	}

