  3	namespace Modules\AI\Actions;
  4	
  5	use Exception;
  6	use Modules\AI\Contracts\QueueAiRaid;
  7	use Modules\AI\Domain\Perception\ActivityIntelReader;
  8	use Modules\AI\Enums\AiQueueActionReason;
  9	use Modules\AI\Support\AiActionResult;
 10	use OGame\Factories\PlanetServiceFactory;
 11	use OGame\GameMissions\AttackMission;
 12	use OGame\GameObjects\Models\Units\UnitCollection;
 13	use OGame\Models\Enums\PlanetType;
 14	use OGame\Models\Planet;
 15	use OGame\Models\Planet\Coordinate;
 16	use OGame\Models\Resources;
 17	use OGame\Services\FleetMissionService;
 18	use OGame\Services\ObjectService;
 19	use OGame\Services\PlanetService;
 20	use OGame\Services\PlayerGameStateService;
 21	
 22	/**
 23	 * Module-owned adapter over the host's attack fleet path.
 24	 *
 25	 * The decision and the target are the module's; the mission, its legality and the
 26	 * battle itself are the host's. The raiding fleet is the origin planet's own
 27	 * ships, deducted atomically by the host's mission start.
 28	 */
 29	class QueueAiRaidAction implements QueueAiRaid
 30	{
 31	    public function __construct(
 32	        private PlayerGameStateService $playerGameStateService,
 33	        private PlanetServiceFactory $planetServiceFactory,
 34	        private ActivityIntelReader $activityIntelReader,
 35	    ) {
 36	    }
 37	
 38	    public function handle(int $playerId, int $originPlanetId, int $targetGalaxy, int $targetSystem, int $targetPosition, int $targetType, ?array $launchUnits = null): AiActionResult
 39	    {
 40	        if (!Planet::query()->whereKey($originPlanetId)->where('user_id', $playerId)->exists()) {
 41	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 42	        }
 43	
 44	        try {
 45	            $player = $this->playerGameStateService->advance($playerId, $originPlanetId);
 46	
 47	            if ($player->isBanned()) {
 48	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 49	            }
 50	            if ($player->isInVacationMode()) {
 51	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 52	            }
 53	
 54	            $origin = $this->planetServiceFactory->makeForPlayer($player, $originPlanetId, false);
 55	
 56	            $targetCoordinate = new Coordinate($targetGalaxy, $targetSystem, $targetPosition);
 57	
 58	            // Between planning and dispatch the target may have logged in. The
 59	            // activity star is galaxy-visible, so flying into a just-touched
 60	            // target is a recall or a ninja, not a raid (RAID-010) -- unless the
 61	            // neighbour holds a wall: a fleet parked at home can be fleetsaved out
 62	            // of the way and loose resources spent, but a wall and the pile it
 63	            // covers stay where they are, so that haul is still there to take
 64	            // (LIFE_FIGHTS).
 65	            $target = $this->planetServiceFactory->makeForCoordinate($targetCoordinate, false, PlanetType::from($targetType));
 66	            if ($target !== null && $this->activityIntelReader->activityAt($target) && $target->getDefenseUnits()->units === []) {
 67	                return AiActionResult::rejected(AiQueueActionReason::TargetActiveAtDispatch);
 68	            }
 69	
 70	            // A moon active while its planet is quiet is the defender moving a
 71	            // fleet on the moon — staging the trap a raid would fly into
 72	            // (NIN-005). Flying into it is a ninja, not a raid.
 73	            $moon = $this->planetServiceFactory->makeMoonForCoordinate($targetCoordinate);
 74	            if ($moon !== null && $target !== null && $this->activityIntelReader->moonOnlyActivity($moon, $target)) {
 75	                return AiActionResult::rejected(AiQueueActionReason::TargetStagingAtDispatch);
 76	            }
 77	
 78	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
 79	            $fleet = $this->launchFleet($origin, $launchUnits);
 80	
 81	            // The host refuses a flight the origin cannot pay the fuel for; spending deuterium on
 82	            // mines or ferries between planning and dispatch is how a planned raid ends up here.
 83	            $fuel = (float) $fleetMissions->calculateConsumption($origin, $fleet, $targetCoordinate, 0, 10.0);
 84	            if ($fuel > floor($origin->deuterium()->get())) {
 85	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 86	            }
 87	            // The host refuses a flight the fleet's own tanks cannot hold the fuel for ("insufficient
 88	            // storage capacity"); a long route flown by a small subset is how a planned raid ends up here.
 89	            if ($fuel > $fleet->getTotalFuelCapacity($player)) {
 90	                return AiActionResult::rejected(AiQueueActionReason::FuelTankShort);
 91	            }
 92	
 93	            $mission = $fleetMissions->createNewFromPlanet(
 94	                $origin,
 95	                $targetCoordinate,
 96	                PlanetType::from($targetType),
 97	                AttackMission::getTypeId(),
 98	                $fleet,
 99	                new Resources(),
100	                10,
101	            );
102	
103	            return AiActionResult::queued($mission->id);
104	        } catch (Exception $exception) {
105	            return AiActionResult::rejected($exception->getMessage());
106	        }
107	    }
108	
109	    /**
110	     * The fleet the raid flies: the counter-selected subset, or the whole origin fleet when the
111	     * intent carried no subset (an older work item). The host still owns what the planet holds.
112	     *
113	     * @param array<string, int>|null $launchUnits
114	     */
115	    private function launchFleet(PlanetService $origin, ?array $launchUnits): UnitCollection
116	    {
117	        if ($launchUnits === null || $launchUnits === []) {
118	            return $origin->getShipUnits();
