 99	     * does not list leaves the account bare no longer.
100	     */
101	    private function unreadInbound(PlayerService $player, FleetMissionService $missions): ThreatResponsePlan
102	    {
103	        if (! $missions->currentPlayerUnderAttack()) {
104	            return app()->makeWith(ThreatResponsePlan::class, ['underAttack' => false]);
105	        }
106	
107	        $wall = [];
108	        foreach ($player->planets->all() as $planet) {
109	            $wall[$planet->getPlanetId()] = [AiThreatResponse::ReinforceDefense];
110	        }
111	
112	        return app()->makeWith(ThreatResponsePlan::class, ['underAttack' => true, 'responses' => $wall]);
113	    }
114	
115	    /**
116	     * The wall a threatened body's reinforcement is sized to: what its own exposure asks for, or what a
117	     * fleet the account keeps home wants behind it to be bait, whichever is more. Null when the wall
118	     * already covers both, which is the answer the unit planner reads as "nothing to reinforce".
119	     *
120	     * The need is a value, so how many units that is and which of them stays the composition planner's
121	     * question; a bait need names the fleet it is covering as the protected value, so a trace can show
122	     * why the wall grew rather than only that it did.
123	     */
124	    public function reinforcementNeed(PlayerService $player, PlanetService $planet, ?DefenseNeed $exposure): ?DefenseNeed
125	    {
126	        $fleet = $this->movableFleetValue($player, $planet);
127	        if ($fleet <= 0.0) {
128	            return $exposure;
129	        }
130	
131	        $bait = $this->baitRatio() * $fleet;
132	        if (($exposure?->defenceValue ?? 0.0) >= $bait || $this->wallValue($planet) >= $bait) {
133	            return $exposure;
134	        }
135	
136	        return app()->makeWith(DefenseNeed::class, [
137	            'defenceValue' => $bait,
138	            'reason' => 'defense:need:bait',
139	            'protectedValue' => $fleet,
140	            'currentDefenseValue' => $this->wallValue($planet),
141	            'threatBand' => 'inbound',
142	            'intent' => 'reinforce',
143	        ]);
144	    }
145	
146	    /**
147	     * What this body answers the inbound with, in the order the account acts on it: the fleet first, it
148	     * is what the trip is for, then the stock, then the wall.
149	     *
150	     * The two fleet answers exclude each other, and so does the stock: the save and the ferry both need
151	     * the body's hulls, so a body whose fleet is leaving has nothing left at home to carry its pile with
152	     * and the pile stays where it is.
153	     *
154	     * @param array<int, int> $threatenedPlanetIds every body this same inbound is aimed at
155	     * @param array<int, QueueableTransfer> $evacuations filled with the ferry a body that carries its stock off flies
156	     * @return list<AiThreatResponse>
157	     */
158	    private function responsesFor(PlayerService $player, PlanetService $planet, ?QueueableFleetSave $save, array $threatenedPlanetIds, array &$evacuations): array
159	    {
160	        $fleet = $this->movableFleetValue($player, $planet);
161	        $answer = $this->fleetResponse($planet, $save, $fleet);
162	        $leaving = $answer === AiThreatResponse::EvacuateFleet;
163	        $responses = $answer === null ? [] : [$answer];
164	
165	        // The save and the ferry both need this body's hulls, so a body whose fleet is leaving has
166	        // nothing left at home to carry its pile with and the pile stays where it is. Which sibling
167	        // receives it and what fits in the holds stays the ferry planner's and the adapter's question.
168	        if (! $leaving) {
169	            $ferry = $this->transfer->evacuationPlan($player->getId(), $planet->getPlanetId(), $threatenedPlanetIds);
170	            if ($ferry instanceof QueueableTransfer) {
171	                $responses[] = AiThreatResponse::EvacuateResources;
172	                $evacuations[$planet->getPlanetId()] = $ferry;
173	            }
174	        }
175	
176	        // The wall: what this body stands to lose, or what a fleet kept home behind it needs.
177	        if ($this->defenseNeed->evaluate($player, $planet) !== null || $this->baitStillOwesWall($planet, $fleet)) {
178	            $responses[] = AiThreatResponse::ReinforceDefense;
179	        }
180	
181	        return $responses === [] ? [AiThreatResponse::DoNothing] : $responses;
182	    }
183	
184	    /**
185	     * The fleet's own answer to the inbound: it leaves, it stays home as bait, or there is nothing this
186	     * body can do for it. The two answers exclude each other, because a fleet that leaves cannot also be
187	     * held.
188	     */
189	    private function fleetResponse(PlanetService $planet, ?QueueableFleetSave $save, float $fleet): ?AiThreatResponse
190	    {
191	        if ($save !== null && $save->originPlanetId === $planet->getPlanetId()) {
192	            return AiThreatResponse::EvacuateFleet;
193	        }
194	
195	        if ($fleet <= 0.0 || $this->wallValue($planet) < $this->baitRatio() * $fleet) {
196	            return null;
197	        }
198	
199	        return AiThreatResponse::AttemptNinja;
200	    }
201	
202	    /**
203	     * Whether a wall still has to be bought for a fleet the account is keeping home: the hold is not an
204	     * ambush until the wall stands at the file's multiple of what that fleet is worth.
205	     */
206	    private function baitStillOwesWall(PlanetService $planet, float $fleet): bool
207	    {
208	        return $fleet > 0.0 && $this->wallValue($planet) < $this->baitRatio() * $fleet;
209	    }
210	
211	    /**
212	     * The own bodies a foreign, non-espionage fleet is aimed at. A probe alone is not an attack (FS-012),
213	     * so it produces no response; which mission types count stays the host's own answer.
214	     *
215	     * @return array<int, true>
216	     */
217	    private function threatenedPlanetIds(PlayerService $player, FleetMissionService $missions): array
218	    {
219	        $threatened = [];
220	
221	        foreach ($missions->getActiveFleetMissionsForCurrentPlayer() as $mission) {
222	            if ($mission->user_id !== $player->getId() && $mission->mission_type !== EspionageMission::getTypeId()) {
223	                $threatened[(int) $mission->planet_id_to] = true;
224	            }
225	        }
226	
227	        return $threatened;
228	    }
229	
230	    /** The metal-equivalent value of the hulls this body could fly away with, satellites excluded. */
231	    private function movableFleetValue(PlayerService $player, PlanetService $planet): float
232	    {
233	        $value = 0.0;
234	
235	        foreach (MovableFleet::of($player, $planet->getShipUnits())->toArray() as $machineName => $amount) {
236	            $value += $this->metalEquivalent(ObjectService::getObjectRawPrice($machineName)) * $amount;
237	        }
238	
239	        return $value;
240	    }
241	
242	    /** The metal-equivalent value of the wall this body stands, built defence only. */
243	    private function wallValue(PlanetService $planet): float
244	    {
245	        $value = 0.0;
246	
247	        foreach ($planet->getDefenseUnits()->toArray() as $machineName => $amount) {
248	            $value += $this->metalEquivalent(ObjectService::getObjectRawPrice($machineName)) * $amount;
249	        }
250	
251	        return $value;
252	    }
253	
254	    private function metalEquivalent(Resources $resources): float
255	    {
256	        return $resources->metal->get()
257	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
258	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
259	    }
260	
261	    /**
262	     * The multiple of a held fleet's value its wall has to reach, from the behaviour file. A file
263	     * without the number states no ambush at all, which is an error rather than a silent default.
264	     */
265	    private function baitRatio(): float
266	    {
267	        if ($this->ratio !== null) {
268	            return $this->ratio;
269	        }
270	
271	        $parsed = Yaml::parseFile($this->policyFile ?? module_path('AI', self::POLICY_FILE));
272	        $ratio = is_array($parsed) ? ($parsed['bait_ratio'] ?? null) : null;
273	
274	        if (! is_numeric($ratio) || (float) $ratio <= 0.0) {
275	            throw new RuntimeException('threat-response: the file must state a positive bait_ratio.');
276	        }
277	
278	        return $this->ratio = (float) $ratio;
279	    }
280	}

