 19	/**
 20	 * Play the cohort forward by simulated hours without waiting for any of them.
 21	 *
 22	 * The game is calculation over timestamps, so this command owns the clock: it freezes Carbon at an
 23	 * instant, runs everything that is due at that instant (fleet arrivals, the module's due work, the
 24	 * once-a-while maintenance commands the scheduler would fire), then jumps straight to the next instant
 25	 * anything is due. A quiet night costs one jump, not eight hours. The routines, waking windows and
 26	 * night rest stay real, because the sessions read the simulated clock; nothing is accelerated or
 27	 * bypassed, which is the difference from `ai.population.session_interval_seconds`.
 28	 *
 29	 * DEV TOOLING, write-heavy: it moves a database into the future, so it only runs on a database whose
 30	 * name says it is a simulation copy (`ogamex-sim...`), never on the live cohort. `bash scripts/ogamex
 31	 * sim` clones the cohort into one, runs this and reads the scorecard and invariants back at the
 32	 * simulated instant.
 33	 */
 34	#[Description('Advance simulated game time and play the AI cohort through it without waiting.')]
 35	#[Signature('ai:sim
 36	    {--hours=24 : Simulated hours to play}
 37	    {--from= : Start instant (default: where the last run on this database stopped, else the real now)}
 38	    {--accounts= : Play only the first N enabled accounts}
 39	    {--max-step=900 : Longest jump in simulated seconds when nothing is due}
 40	    {--maintenance=900 : Simulated seconds between campaign, alliance and score-sample passes}
 41	    {--highscore-every=3600 : Simulated seconds between the three highscore generators (each walks every player; the real schedule runs them every 300 s)}
 42	    {--max-wall= : Stop after this many real seconds and keep the state, so a later run continues}
 43	    {--native-cognition : Opt-in only: skip the Fatima/CBRKit/AgentOS sidecars and the language lane and play on the native engines}
 44	    {--ffi-probe : Diagnose the Rust segfault: call the library with an empty fight after every phase of every jump and print which phase last survived}
 45	    {--workers=1 : Fork this many processes per simulated instant, each running a share of the due sessions against the sidecars at the same time}
 46	    {--keep-accelerated : Keep ai.population.session_interval_seconds instead of playing real routines}
 47	    {--max-errors=300 : Abort when this many errors pile up with no session having run (a broken build, not a result)}
 48	    {--force-db : Allow a database whose name does not contain "sim"}')]
 49	class SimulateAiTime extends Command
 50	{
 51	    private const PASSES_PER_INSTANT = 40;
 52	
 53	    private const BATCH = 500;
 54	
 55	    /** @var array<string, int> */
 56	    private array $errors = [];
 57	
 58	    /** @var array<string, array{0: float, 1: int}> seconds and calls per phase, printed as PROFILE at the end */
 59	    private array $profile = [];
 60	
 61	    private CarbonImmutable|null $nextHighscore = null;
 62	
 63	    public function handle(): int
 64	    {
 65	        $database = (string) DB::connection()->getDatabaseName();
 66	
 67	        if (!str_contains(strtolower($database), 'sim') && !$this->option('force-db')) {
 68	            $this->error("Refusing to move [{$database}] into the future: the name must contain \"sim\" (or pass --force-db).");
 69	
 70	            return self::FAILURE;
 71	        }
 72	
 73	        config(['queue.default' => 'sync']);
 74	        if ($this->option('native-cognition')) {
 75	            config([
 76	                'ai.cognition.mode' => 'native',
 77	                'ai.cognition.memory.driver' => 'native',
 78	                'ai.cognition.experience.driver' => 'native',
 79	                'ai.cognition.conversation.enabled' => false,
 80	                'ai.language.enabled' => false,
 81	            ]);
 82	            Http::preventStrayRequests();
 83	        }
 84	        if (!$this->option('native-cognition')) {
 85	            $this->probeSidecars();
 86	        }
 87	        if (!$this->option('keep-accelerated')) {
 88	            config(['ai.population.session_interval_seconds' => 0]);
 89	        }
 90	
 91	        SimulatedTime::release();
 92	        $stateFile = storage_path('app/ai-sim/' . preg_replace('/[^A-Za-z0-9_.-]/', '_', $database) . '.txt');
 93	        $start = $this->startInstant($stateFile);
 94	        $end = $start->addSeconds((int) round((float) $this->option('hours') * 3600));
 95	        $players = $this->players();
 96	
 97	        if ($players === []) {
 98	            $this->error('No enabled AI account in this database.');
 99	
100	            return self::FAILURE;
101	        }
102	
103	        $this->info(sprintf('SIM: %s -> %s (%.1f h), %d account(s), database %s', $start->toIso8601String(), $end->toIso8601String(), $start->floatDiffInHours($end), count($players), $database));
104	
105	        $this->ffiProbe('before the first jump');
106	        $wallStart = microtime(true);
107	        $wallLimit = $this->option('max-wall') === null ? null : (float) $this->option('max-wall');
108	        $maintenanceEvery = max(60, (int) $this->option('maintenance'));
109	        $maxStep = max(1, (int) $this->option('max-step'));
110	        $now = $start;
111	        $nextMaintenance = $start;
112	        $hourIndex = -1;
113	        $hour = ['sessions' => 0, 'other' => 0, 'errors' => 0];
114	        $total = ['sessions' => 0, 'other' => 0, 'errors' => 0];
115	        $stoppedEarly = false;
116	        $jumps = 0;
117	
118	        while ($now->lessThan($end)) {
119	            SimulatedTime::freezeAt($now);
120	            $this->ffiProbe('jump ' . $jumps . ' after the clock moved to ' . $now->toIso8601String());
121	
122	            // One commit per simulated instant instead of one per statement group: every session and order
123	            // writes dozens of rows, and each commit is an fsync. Inner transactions become savepoints.
124	            $drain = function () use ($players): array {
125	                $this->timed('fleet arrivals', fn () => $this->runFleetArrivals());
126	
127	                return $this->timed('due work (all sessions and orders)', fn (): array => $this->drainDueWork($players));
128	            };
129	            // Forked workers each need their own connection, so the one-commit-per-instant wrapper only applies to a single process.
130	            $ran = $this->workerCount() > 1 ? $drain() : DB::transaction($drain);
131	            foreach ($ran as $key => $count) {
132	                $hour[$key] += $count;
133	                $total[$key] += $count;
134	            }
135	
136	            $this->ffiProbe('jump ' . $jumps . ' after due work');
137	
138	            if ($now->greaterThanOrEqualTo($nextMaintenance)) {
139	                $this->runMaintenance($now);
140	                $this->ffiProbe('jump ' . $jumps . ' after maintenance');
141	                $nextMaintenance = $now->addSeconds($maintenanceEvery);
142	            }
143	
144	            $currentHour = (int) floor($start->diffInSeconds($now) / 3600);
145	            if ($currentHour !== $hourIndex) {
146	                if ($hourIndex >= 0) {
147	                    $this->reportHour($start->addHours($hourIndex), $hour);
148	                }
149	                $hourIndex = $currentHour;
150	                $hour = ['sessions' => 0, 'other' => 0, 'errors' => 0];
151	            }
152	
153	            if ($total['errors'] >= max(1, (int) $this->option('max-errors')) && $total['sessions'] === 0) {
154	                $this->error('SIM ABORTED: ' . $total['errors'] . ' errors and no session has run -- the build is broken, the numbers would mean nothing.');
155	                $this->reportErrors();
156	
157	                return self::FAILURE;
158	            }
159	
160	            if ($wallLimit !== null && microtime(true) - $wallStart > $wallLimit) {
161	                $stoppedEarly = true;
162	
163	                break;
164	            }
165	
166	            $now = $this->timed('next-instant queries', fn (): CarbonImmutable => $this->nextInstant($now, $end, $nextMaintenance, $players, $maxStep));
167	            $jumps++;
168	        }
169	
170	        if ($hourIndex >= 0) {
171	            $this->reportHour($start->addHours($hourIndex), $hour);
172	        }
173	
174	        $stoppedAt = $stoppedEarly ? $now : $end;
175	        SimulatedTime::freezeAt($stoppedAt);
176	        @mkdir(dirname($stateFile), 0775, true);
177	        file_put_contents($stateFile, $stoppedAt->toIso8601String());
178	
179	        $this->reportErrors();
180	        $this->line(sprintf('JUMPS: %d (average %.0f simulated seconds per jump)', $jumps, $start->diffInSeconds($stoppedAt) / max(1, $jumps)));
181	        $this->reportProfile();
182	        $wall = max(0.001, microtime(true) - $wallStart);
183	        $simulated = $start->diffInSeconds($stoppedAt);
184	        $this->info(sprintf(
185	            'SIM_NOW: %s',
186	            $stoppedAt->toIso8601String(),
187	        ));
188	        $this->info(sprintf(
189	            'SIM: %s h played in %.0f s (x%.0f), %d session(s), %d other work item(s), %d error(s)%s',
190	            number_format($simulated / 3600, 1),
191	            $wall,
192	            $simulated / $wall,
193	            $total['sessions'],
194	            $total['other'],
195	            $total['errors'],
196	            $stoppedEarly ? ' -- stopped at --max-wall, run again to continue' : '',
197	        ));
198	
199	        return self::SUCCESS;
200	    }
