202	    /** @template T @param callable(): T $work @return T */
203	    private function timed(string $phase, callable $work): mixed
204	    {
205	        $started = microtime(true);
206	
207	        try {
208	            return $work();
209	        } finally {
210	            $this->profile[$phase] ??= [0.0, 0];
211	            $this->profile[$phase][0] += microtime(true) - $started;
212	            $this->profile[$phase][1]++;
213	        }
214	    }
215	
216	    private function reportProfile(): void
217	    {
218	        uasort($this->profile, fn (array $a, array $b): int => $b[0] <=> $a[0]);
219	        $this->line('PROFILE (real seconds spent per phase, biggest first):');
220	        foreach ($this->profile as $phase => [$seconds, $calls]) {
221	            $this->line(sprintf('  %8.1f s  %6d call(s)  %7.3f s/call  %s', $seconds, $calls, $seconds / max(1, $calls), $phase));
222	        }
223	    }
