225	    private function startInstant(string $stateFile): CarbonImmutable
226	    {
227	        if ($this->option('from')) {
228	            return CarbonImmutable::parse((string) $this->option('from'));
229	        }
230	
231	        if (is_file($stateFile)) {
232	            return CarbonImmutable::parse(trim((string) file_get_contents($stateFile)));
233	        }
234	
235	        return CarbonImmutable::now();
236	    }
