238	    /** @return list<int> */
239	    private function players(): array
240	    {
241	        $query = AiProfile::query()->where('enabled', true)->orderBy('player_id');
242	
243	        if ($this->option('accounts') !== null) {
244	            $query->limit(max(1, (int) $this->option('accounts')));
245	        }
246	
247	        return $query->pluck('player_id')->map(fn ($id): int => (int) $id)->all();
248	    }
