250	    private function runFleetArrivals(): void
251	    {
252	        // The command walks the overdue backlog; calling it when nothing has landed is pure overhead.
253	        $due = DB::table('fleet_missions')->where('processed', 0)->where('time_arrival', '<=', SimulatedTime::now()->getTimestamp())->exists();
254	        if (!$due) {
255	            return;
256	        }
257	
258	        try {
259	            Artisan::call('ogamex:scheduler:process-fleet-arrivals', ['--limit' => self::BATCH]);
260	        } catch (Throwable $exception) {
261	            $this->noteError('fleet arrivals: ' . $exception->getMessage());
262	        }
263	    }
