265	    /**
266	     * Everything the real scheduler would fire during a stretch of minutes: campaign, alliance and
267	     * score-sample passes, language reconciliation and the three highscore generators the module
268	     * runs on the first tick of each five-minute window.
269	     */
270	    private function runMaintenance(CarbonImmutable $now): void
271	    {
272	        $commands = [
273	            'ai:advance-campaigns',
274	            'ai:advance-alliance-life',
275	            'ai:reconcile-language-requests',
276	            'ai:record-score-samples',
277	            'ai:run-campaign',
278	        ];
279	
280	        // The highscore generators walk every player and rank them; at the real five-minute cadence they
281	        // dominated a simulated quarter hour, and nothing the cohort decides reads them that often.
282	        if ($this->nextHighscore === null || $now->greaterThanOrEqualTo($this->nextHighscore)) {
283	            array_push($commands, 'ogamex:scheduler:generate-highscores', 'ogamex:scheduler:generate-alliance-highscores', 'ogamex:scheduler:generate-highscore-ranks');
284	            $this->nextHighscore = $now->addSeconds(max(300, (int) $this->option('highscore-every')));
285	        }
286	
287	        foreach ($commands as $command) {
288	            try {
289	                $this->timed('maintenance: ' . $command, fn (): int => Artisan::call($command));
290	            } catch (Throwable $exception) {
291	                $this->noteError($command . ': ' . $exception->getMessage());
292	            }
293	        }
294	    }
