296	    /**
297	     * Run every work item due at the frozen instant, orders before sessions, and repeat because a
298	     * session can make more work due now. Returns what ran, split into sessions and other work.
299	     *
300	     * @param list<int> $players
301	     * @return array{sessions: int, other: int, errors: int}
302	     */
303	    private function drainDueWork(array $players): array
304	    {
305	        $ran = ['sessions' => 0, 'other' => 0, 'errors' => 0];
306	        $attempted = [];
307	
308	        for ($pass = 0; $pass < self::PASSES_PER_INSTANT; $pass++) {
309	            $due = $this->dueQuery($players)
310	                ->orderByRaw('kind = ? asc', [AiWorkKind::RunSession->value])
311	                ->orderBy('due_at')
312	                ->limit(self::BATCH)
313	                ->get(['id', 'kind'])
314	                ->reject(fn (object $row): bool => isset($attempted[$row->id]));
315	
316	            if ($due->isEmpty()) {
317	                break;
318	            }
319	
320	            foreach ($due as $row) {
321	                $attempted[$row->id] = true;
322	            }
323	
324	            foreach ($this->runRows($due->values()->all()) as $key => $count) {
325	                $ran[$key] += $count;
326	            }
327	        }
328	
329	        return $ran;
330	    }
