332	    /**
333	     * Calls the shared Rust binding with a trivial input (it only has to reach the library's first libc call) and
334	     * prints the label to stderr unbuffered, so when the process dies the last line names the phase that broke it.
335	     */
336	    private function ffiProbe(string $label): void
337	    {
338	        if (!$this->option('ffi-probe')) {
339	            return;
340	        }
341	
342	        try {
343	            $binding = \OGame\GameMissions\BattleEngine\RustBattleEngine::binding();
344	            $pointer = $binding->fight_battle_rounds('{}');
345	            if ($pointer !== null) {
346	                $binding->free_battle_result($pointer);
347	            }
348	            fwrite(STDERR, "FFI-PROBE ok   {$label}\n");
349	        } catch (Throwable $exception) {
350	            fwrite(STDERR, "FFI-PROBE threw {$label}: " . $exception->getMessage() . "\n");
351	        }
352	    }
353	
354	    private function workerCount(): int
355	    {
356	        $workers = max(1, (int) $this->option('workers'));
357	
358	        if ($workers > 1 && !function_exists('pcntl_fork')) {
359	            return 1;
360	        }
361	
362	        return $workers;
363	    }
