365	    /**
366	     * Run the due rows: in this process, or split across forked workers that all stand at the same simulated
367	     * instant. A session spends most of its wall time waiting on the sidecars, so concurrent sessions overlap
368	     * those waits. Sessions of different accounts already run concurrently in production.
369	     *
370	     * @param list<object> $rows
371	     * @return array{sessions: int, other: int, errors: int}
372	     */
373	    private function runRows(array $rows): array
374	    {
375	        $workers = $this->workerCount();
376	
377	        if ($workers <= 1 || count($rows) < $workers * 2) {
378	            return $this->processRows($rows);
379	        }
380	
381	        // No open connection may cross the fork: a child closing a shared socket would cut the parent's session.
382	        DB::purge();
383	        $directory = sys_get_temp_dir() . '/ai-sim-' . getmypid() . '-' . bin2hex(random_bytes(3));
384	        @mkdir($directory);
385	        $children = [];
386	
387	        foreach (range(0, $workers - 1) as $index) {
388	            $share = array_values(array_filter($rows, fn (int $position): bool => $position % $workers === $index, ARRAY_FILTER_USE_KEY));
389	            $pid = pcntl_fork();
390	
391	            if ($pid === 0) {
392	                $this->errors = [];
393	                $result = $this->processRows($share);
394	                file_put_contents("{$directory}/{$index}.json", json_encode(['ran' => $result, 'errors' => $this->errors]));
395	                DB::purge();
396	
397	                exit(0);
398	            }
399	
400	            $children[$index] = $pid;
401	        }
402	
403	        $total = ['sessions' => 0, 'other' => 0, 'errors' => 0];
404	        foreach ($children as $index => $pid) {
405	            pcntl_waitpid($pid, $status);
406	            $file = "{$directory}/{$index}.json";
407	            $report = is_file($file) ? json_decode((string) file_get_contents($file), true) : null;
408	
409	            if (!is_array($report)) {
410	                $total['errors']++;
411	                $this->noteError("worker {$index} died without a report (status {$status})");
412	
413	                continue;
414	            }
415	
416	            foreach ($report['ran'] as $key => $count) {
417	                $total[$key] += $count;
418	            }
419	            foreach ($report['errors'] as $message => $count) {
420	                $this->errors[$message] = ($this->errors[$message] ?? 0) + $count;
421	            }
422	            @unlink($file);
423	        }
424	        @rmdir($directory);
425	
426	        return $total;
427	    }
