546	    /** @param array{sessions: int, other: int, errors: int} $hour */
547	    private function reportHour(CarbonImmutable $hourStart, array $hour): void
548	    {
549	        $this->line(sprintf('  %s  sessions %-4d other %-4d errors %d', $hourStart->format('Y-m-d H:00'), $hour['sessions'], $hour['other'], $hour['errors']));
550	    }
551	
552	    private function noteError(string $message): void
553	    {
554	        $key = mb_substr(preg_replace('/\d+/', 'N', $message) ?? $message, 0, 160);
555	        $this->errors[$key] = ($this->errors[$key] ?? 0) + 1;
556	    }
557	
558	    private function reportErrors(): void
559	    {
560	        if ($this->errors === []) {
561	            return;
562	        }
563	
564	        arsort($this->errors);
565	        $this->warn('Errors by kind (numbers folded to N):');
566	        foreach (array_slice($this->errors, 0, 8, true) as $message => $count) {
567	            $this->line(sprintf('  %5d  %s', $count, $message));
568	        }
569	    }
570	}

