13	// DISPATCH_REFUSALS: a refused dispatch is not a mission, so until the first refusal of a batch lands
14	// nothing the host holds remembers the fleet already on its way to a target (measured 4 Oct 2026: one
15	// account's target refused seven times in six hours for being active). The raid lane is the one that
16	// plans per report, and a probe volley writes one report per probe: the farm with two reports is the
17	// story, and its coordinate has to hold one fleet however many reports name it.
18	
19	/** The raid story the two cases share: an undefended inactive, two reports on it, cargo and a kill ship. */
20	function oneRaidPerTargetSeries(object $test): Situation
21	{
22	    return Situation::of($test)
23	        ->archetype(AiArchetype::Fleeter)
24	        ->research('combustion_drive', 6)
25	        ->ships('large_cargo', 20)
26	        ->ships('light_fighter', 10)
27	        ->resources(200_000, 200_000, 500_000)
28	        ->inactiveNeighbour(daysQuiet: 10, metal: 400_000, crystal: 200_000)
29	        ->spyReport()
30	        ->spyReport();
31	}
32	
33	test('two reports of one neighbour are one raid, not a queue of fleets', function (): void {
34	    // The login decides and nothing has flown yet, so an intent is the only trace of the fleet it placed.
35	    oneRaidPerTargetSeries($this)->session(rounds: 0);
36	
37	    $raidTargets = AiWorkItem::query()
38	        ->where('player_id', $this->currentUserId)
39	        ->where('kind', AiWorkKind::Raid)
40	        ->get(['payload'])
41	        ->map(static fn (AiWorkItem $item): string => ($item->payload['target_galaxy'] ?? '?') . ':' . ($item->payload['target_system'] ?? '?') . ':' . ($item->payload['target_position'] ?? '?'));
42	
43	    expect($raidTargets)->toHaveCount(1);
44	});
45	
46	// At the bound from the other side: holding the target must not park the fleet, so the raid the login
47	// decided still leaves when its intent comes due.
48	test('the raid the login decided still flies once its intent is executed', function (): void {
49	    oneRaidPerTargetSeries($this)->session(rounds: 0)->session()->expectMission('Attack');
50	});

